// Compact wording only in the quick-buy rail; native pass descriptions remain full.
export function mountPassRailCopy(root=document.querySelector('.info-afking')) {
  if (!root) return;
  const changes = [
    [/10 levels · 1 ticket \/ level/g, '10 levels · 1 ticket/level'],
    [/1 ticket \/ level forever/g, '1 ticket/level forever'],
    [/Symbol entries: all colors/g, 'All-color symbols'],
    [/bonus Luckbox/g, 'Luckbox bonus'],
    [/3 gift boons \/ day/g, '3 gift boons/day'],
    [/sDGNRS pool/g, 'sDGNRS'],
    [/High Roller Craps pass/g, 'High Roller pass'],
  ];
  const sync=()=>{
    for(const node of root.querySelectorAll('.pass-shop__perks>span')){
      const original=node.textContent,short=changes.reduce((text,[from,to])=>text.replace(from,to),original);
      if(short===original)continue;
      if(!node.title||node.title===node.dataset.railFullCopy)node.title=original;
      node.dataset.railFullCopy=original;node.textContent=short;
    }
  };
  new MutationObserver(sync).observe(root,{subtree:true,childList:true,characterData:true});sync();
}
